// Regenerates supabase/seed.sql from the sample catalogue in packages/shared.
// Usage: node scripts/generate-seed.ts
import { writeFileSync } from "node:fs";
import { demoBrands, demoCategories, demoProducts } from "../packages/shared/src/demo-data.ts";

const q = (v: string | null | undefined) => (v == null ? "null" : `'${v.replace(/'/g, "''")}'`);
const lines: string[] = [
  "-- Sample catalogue (placeholder prices). Optional: run after 0001_init.sql.",
  "-- Generated by scripts/generate-seed.ts — edit packages/shared/src/demo-data.ts instead.",
  "",
];

for (const c of demoCategories) {
  lines.push(
    `insert into public.categories (name, slug, description, sort_order) values (${q(c.name)}, ${q(c.slug)}, ${q(c.description)}, ${c.sort_order}) on conflict (slug) do nothing;`,
  );
}
lines.push("");
for (const b of demoBrands) {
  lines.push(`insert into public.brands (name, slug) values (${q(b.name)}, ${q(b.slug)}) on conflict (slug) do nothing;`);
}
lines.push("");
for (const p of demoProducts) {
  lines.push(
    `insert into public.products (name, slug, brand_id, category_id, description, highlights, badge, is_featured) values (` +
      `${q(p.name)}, ${q(p.slug)}, ` +
      `(select id from public.brands where slug = ${q(p.brand?.slug)}), ` +
      `(select id from public.categories where slug = ${q(p.category?.slug)}), ` +
      `${q(p.description)}, ${q(JSON.stringify(p.highlights))}::jsonb, ${q(p.badge)}, ${p.is_featured}) on conflict (slug) do nothing;`,
  );
  for (const v of p.variants) {
    lines.push(
      `insert into public.product_variants (product_id, size, flavour, price, mrp, in_stock, sort_order) ` +
        `select id, ${q(v.size)}, ${q(v.flavour)}, ${v.price}, ${v.mrp ?? "null"}, ${v.in_stock}, ${v.sort_order} ` +
        `from public.products where slug = ${q(p.slug)} and not exists (` +
        `select 1 from public.product_variants pv join public.products pp on pp.id = pv.product_id ` +
        `where pp.slug = ${q(p.slug)} and pv.sort_order = ${v.sort_order});`,
    );
  }
  lines.push("");
}

writeFileSync(new URL("../supabase/seed.sql", import.meta.url), lines.join("\n"));
console.log(`Wrote supabase/seed.sql (${demoProducts.length} products)`);
